import numpy as np
D=np.load('/app/output/clear_view_after_probe/depth_topview.npy');D=D[-1] if D.ndim==3 else D;D=D.astype(float)
for th in [1.49,1.47,1.46,1.445,1.44,1.435,1.42,1.4]:
 ys,xs=np.where((D<th)&(np.indices(D.shape)[1]>125)&(np.indices(D.shape)[1]<158)&(np.indices(D.shape)[0]>48)&(np.indices(D.shape)[0]<78))
 print(th,len(xs), (xs.min(),xs.max(),ys.min(),ys.max(),xs.mean(),ys.mean()) if len(xs) else None)
 if th in [1.445,1.44,1.435]:
  for y in range(52,74):
   xx=np.where((D[y,125:158]<th))[0]+125
   if len(xx): print(y,xx.tolist())
PY

